// Prepare the real packaged shell before a clean factory checkpoint is saved.
// The wallpaper oracle is the original/restored grid independently verified in
// E5.5-T05c, not pixels generated by this capture or by the code under test.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import {verifyCleanFactory} from './omarchy-factory-guard.mjs';

const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const quote=text=>"'"+text.replaceAll("'","'\\''")+"'";
const hypr='XDG_RUNTIME_DIR=/run/user/1000 hyprctl -i 0 -j ';
const ipc='OMARCHY_PATH=/usr/share/omarchy XDG_RUNTIME_DIR=/run/user/1000 OMARCHY_SHELL_IPC_TIMEOUT=120s omarchy-shell shell call omarchy.menu ';
export const wallpaperReference=Object.freeze({
  assetSha256:'b149c3e1c8ce383812e7bc3170c2cf8b160ca583d72d59173cd42efdb79ced2b',
  gridSha256:'bde9bbffe9725ffec045f407dab2e6ddbb7dc7365b3307e7ce4f498310d9f289',
  width:1280,height:800,columns:40,rows:24,
  provenance:'E5.5-T05c verified original/alternate/original native wallpaper; cold13-writer-open16, original and restored grids agree',
});

export function wallpaperMatches(bytes) {
  assert.equal(bytes.length,wallpaperReference.columns*wallpaperReference.rows*4);
  return createHash('sha256').update(bytes).digest('hex')===wallpaperReference.gridSha256;
}

// No idle-CPU claim: Qt can keep rendering an already initialized background.
// Require a real interval with no startup jobs, new disk demand or core-process
// replacement. Retain native CPU accounting so continuous rendering is visible.
export function startupWindowReady(samples) {
  if(samples.length<3)return false;
  const window=samples.slice(-3),first=window[0],last=window.at(-1);
  return last.time-first.time>=10000&&
    BigInt(last.clock.mtime)-BigInt(first.clock.mtime)>=20000000n&&
    window.every(row=>row.native.jobs.every(job=>job.exit===0&&job.stdout.trim()==='')&&
      JSON.stringify(row.native.core)===JSON.stringify(first.native.core)&&
      Number.isSafeInteger(row.scheduler.fetchRequestedChunks)&&Number.isSafeInteger(row.scheduler.fetchWaits)&&
      row.scheduler.fetchRequestedChunks===first.scheduler.fetchRequestedChunks&&
      row.scheduler.fetchWaits===first.scheduler.fetchWaits)&&
    BigInt(last.scheduler.retiredInstructions)>BigInt(first.scheduler.retiredInstructions);
}

export async function verifyOmarchyFactoryReady(page,command,output,{name='factory-ready',foot}={}) {
  assert.match(name,/^[a-z0-9-]+$/);assert.ok(foot?.pid>0);
  const report={status:'running',scope:'original GPU shell, matching original wallpaper pixels, trusted Apps open/search/close, completed startup jobs and bounded disk-demand quiet window; no app prelaunch or CPU-idle claim',
    reference:wallpaperReference,started:Date.now(),phases:[],wallpaperSamples:[],startupSamples:[]};
  const save=()=>fs.writeFile(path.join(output,name+'.json'),JSON.stringify(report,null,2)+'\n');
  const run=async text=>{
    assert.ok(Buffer.byteLength(text)<2500,'bounded serial command');
    const result=await command(page,text,300000);
    report.phases.push({command:text,result,time:Date.now()});await save();
    assert.equal(result.exit,0,text);return result.stdout.trim();
  };
  const read=async kind=>JSON.parse(await run(hypr+kind));
  const layer=(layers,namespace)=>Object.values(layers).flatMap(m=>Object.values(m.levels||{}).flat()).find(row=>row.namespace===namespace&&row.alpha>0);
  const until=async(label,readValue,predicate,timeout=300000)=>{
    const deadline=Date.now()+timeout;let value;
    do{value=await readValue();if(predicate(value))return value;await sleep(1500);}while(Date.now()<deadline);
    assert.fail(label+' did not become ready: '+JSON.stringify(value));
  };
  const canvas=page.locator('#ide-display-canvas');
  const press=async key=>{
    await canvas.focus();assert.equal(await page.evaluate(()=>document.documentElement.dataset.keyboardCapture),'on');
    report.phases.push({kind:'trusted-key',key,time:Date.now()});await save();await page.keyboard.press(key,{delay:100});
  };
  const health=async()=>{
    const gpu=await page.evaluate(()=>window.__linuxCtl.gpuStats());
    assert.equal(gpu.qualified,true);assert.equal(gpu.lost,false);assert.equal(gpu.poisoned,false);assert.equal(gpu.disposed,false);
    assert.equal(gpu.counters.failed,0);assert.equal(gpu.counters.cancelled,0);return gpu;
  };
  try {
    report.beforeGpu=await health();
    report.beforeGuard=await verifyCleanFactory(page,command,output,{name:name+'-before-guard'});
    const active=await read('activewindow');
    if(active.class==='org.omarchy.screensaver')await press('Escape');
    assert.ok(!(await read('clients')).some(row=>row.workspace?.id===5),'wallpaper workspace is empty');
    report.originalWorkspace=(await read('activeworkspace')).id;
    assert.equal(report.originalWorkspace,foot.workspace.id);
    await press('Meta+5');
    await until('trusted empty workspace',()=>read('activeworkspace'),row=>row.id===5);
    // Keep the real pointer outside the reference grid, without replacing the
    // cursor or hiding anything in the guest framebuffer.
    const box=await canvas.boundingBox();assert.ok(box?.width>0&&box.height>0);
    await page.mouse.move(box.x+8,box.y+8);
    report.background=await until('mapped original background',()=>read('layers'),rows=>!!layer(rows,'omarchy-background'));
    const assetCode="from pathlib import Path;import hashlib,json;p=Path.home()/'.local/state/omarchy/current/background';q=p.resolve(strict=True);b=q.read_bytes();print(json.dumps(dict(path=str(q),bytes=len(b),sha256=hashlib.sha256(b).hexdigest())))";
    report.asset=JSON.parse(await run('python3 -c '+quote(assetCode)));
    assert.equal(report.asset.sha256,wallpaperReference.assetSha256,'original installed wallpaper');
    const started=Date.now(),clock=await page.evaluate(()=>window.__linuxCtl.guestClockState());let stableSince=null,matches=0;
    while(Date.now()-started<600000){
      const sample=await page.evaluate(async reference=>{
        const c=document.getElementById('ide-display-canvas'),ctx=c.getContext('2d'),data=[];
        if(c.width!==reference.width||c.height!==reference.height)throw Error('original physical wallpaper dimensions required');
        for(let y=0;y<reference.rows;y++)for(let x=0;x<reference.columns;x++)
          data.push(...ctx.getImageData(Math.floor(c.width*(0.1+0.8*x/(reference.columns-1))),Math.floor(c.height*(0.15+0.7*y/(reference.rows-1))),1,1).data);
        return {rgba:data,clock:await window.__linuxCtl.guestClockState(),presentation:window.__presentation.state()};
      },wallpaperReference);
      const bytes=Buffer.from(sample.rgba);delete sample.rgba;
      const matched=wallpaperMatches(bytes),time=Date.now();
      if(matched){matches++;stableSince??=time;}else{matches=0;stableSince=null;}
      const row={time,matched,hash:createHash('sha256').update(bytes).digest('hex'),...sample};report.wallpaperSamples.push(row);
      await health();await save();
      if(matches>=5&&time-stableSince>=5000&&BigInt(sample.clock.mtime)-BigInt(clock.mtime)>=20000000n){
        report.wallpaper={status:'passed',matches,stableMillis:time-stableSince,gridSha256:row.hash};
        await fs.writeFile(path.join(output,name+'-wallpaper.rgba'),bytes);
        await canvas.screenshot({path:path.join(output,name+'-wallpaper.png'),timeout:120000});break;
      }
      await sleep(1500);
    }
    assert.equal(report.wallpaper?.status,'passed','matching original wallpaper has actually finished rendering');
    assert.equal(layer(await read('layers'),'omarchy-menu'),undefined,'Apps is closed before trusted open');
    const inputAt=await page.evaluate(()=>window.__criticTrustedInputEvents.length);
    const opened=Date.now();await press('Meta+Alt+Space');
    report.menu=await until('trusted stock Apps menu',()=>read('layers'),rows=>!!layer(rows,'omarchy-menu'));
    report.menuOpenMs=Date.now()-opened;
    // Read existing upstream methods from the live, loaded menu object. This
    // neither adds a QML diagnostic property nor substitutes on-disk entries for
    // the shell's actual DesktopEntries-backed model.
    report.applicationCount=Number(await run(ipc+'childCount apps'));
    assert.ok(Number.isSafeInteger(report.applicationCount)&&report.applicationCount>=10,'populated native application model');
    report.chromiumEntry=await run(ipc+'pathFor apps.chromium');assert.match(report.chromiumEntry,/Chromium/);
    report.writerEntry=await run(ipc+'pathFor apps.libreoffice-writer');assert.match(report.writerEntry,/LibreOffice Writer/);
    await canvas.screenshot({path:path.join(output,name+'-apps.png'),timeout:120000});
    await canvas.focus();report.phases.push({kind:'trusted-text',text:'libreoffice writer',time:Date.now()});await save();
    await page.keyboard.type('libreoffice writer',{delay:100});
    // Existing read-only pathFor also provides an IPC round trip before the
    // screenshot. The exact search glyphs remain in the independent visual proof.
    assert.match(await run(ipc+'pathFor apps.libreoffice-writer'),/LibreOffice Writer/);
    await canvas.screenshot({path:path.join(output,name+'-writer-search.png'),timeout:120000});
    await press('Escape');
    assert.ok(layer(await read('layers'),'omarchy-menu'),'first Escape clears a nonempty native filter');
    await press('Escape');
    await until('trusted Apps close',()=>read('layers'),rows=>!layer(rows,'omarchy-menu'));
    report.menuTrusted=await page.evaluate(at=>window.__criticTrustedInputEvents.slice(at),inputAt);
    assert.ok(report.menuTrusted.length>=40&&report.menuTrusted.every(row=>row.trusted),'all menu/search events are real browser input');
    await press('Meta+'+report.originalWorkspace);
    await until('original Foot restored',()=>read('activewindow'),row=>row.pid===foot.pid);
    report.launcherService=await run('XDG_RUNTIME_DIR=/run/user/1000 systemctl --user show wayland-wm-app-daemon.service -p ActiveState -p SubState -p Result');
    assert.match(report.launcherService,/ActiveState=active/);assert.match(report.launcherService,/Result=success/);
    const nativeCode=`from pathlib import Path;import os,json,subprocess;core=[]
for p in Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  if p.stat().st_uid!=1000:continue
  comm=(p/'comm').read_text().strip()
  if comm not in ('Hyprland','quickshell','foot'):continue
  fields=(p/'stat').read_text().rsplit(')',1)[1].split();core.append(dict(pid=int(p.name),comm=comm,starttime=fields[19]))
 except FileNotFoundError:continue
jobs=[]
for scope in ([],['--user']):
 r=subprocess.run(['systemctl']+scope+['list-jobs','--no-legend','--no-pager','--plain'],capture_output=True,text=True);jobs.append(dict(scope=scope,exit=r.returncode,stdout=r.stdout,stderr=r.stderr))
print(json.dumps(dict(core=sorted(core,key=lambda r:r['pid']),jobs=jobs,cpu=Path('/proc/stat').read_text().splitlines()[0],uptime=Path('/proc/uptime').read_text().strip())))`;
    const settleDeadline=Date.now()+600000;
    do{
      const native=JSON.parse(await run('XDG_RUNTIME_DIR=/run/user/1000 python3 -c '+quote(nativeCode)));
      assert.ok(native.core.some(row=>row.pid===foot.pid&&row.comm==='foot'));
      for(const comm of ['Hyprland','quickshell'])assert.ok(native.core.some(row=>row.comm===comm));
      const worker=await page.evaluate(async()=>({clock:await window.__linuxCtl.guestClockState(),scheduler:await window.__linuxCtl.schedulerStats()}));
      report.startupSamples.push({time:Date.now(),native,...worker});await health();await save();
      if(startupWindowReady(report.startupSamples)){report.startup={status:'passed',samples:report.startupSamples.slice(-3)};break;}
      await sleep(5000);
    }while(Date.now()<settleDeadline);
    assert.equal(report.startup?.status,'passed','startup jobs finish and disk demand settles before capture');
    report.afterGuard=await verifyCleanFactory(page,command,output,{name:name+'-after-guard'});
    assert.deepEqual(await page.evaluate(()=>window.__keyboardCapture.heldSnapshot()),[],'no held factory keys');
    report.afterGpu=await health();assert.equal(report.afterGpu.epoch,report.beforeGpu.epoch);
    assert.ok(report.afterGpu.counters.draws>report.beforeGpu.counters.draws,'real preparation renders new guest work');
    report.status='passed';return report;
  }catch(error){report.status='failed';report.error=error.stack;throw error;}
  finally{report.finished=Date.now();await save();}
}
